/**
 * Compatibility tests against vectors produced by the original v1.3.3.7 bundle.
 *
 * Every vector in tests/fixtures/golden.json was generated by executing the
 * legacy minified `0.js` inside a VM with a seeded `Math.random`. If this suite
 * is green, sessions created by the new code are interchangeable with sessions
 * created by the old one and with the OAST server.
 */

import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import {
  correlationIdFromKey,
  encodeLabel,
  interactionLabel,
  keyToBase64,
  normalizeKeyB64,
  bytesToBigInt,
  bigIntToBase36
} from "../src/js/core/crypto.js";
import { bytesToBase64, base64ToUtf8, utf8ToBase64, hexToBytes } from "../src/js/core/encoding.js";
import { SessionGenerator, buildPrivateUrl } from "../src/js/core/generator.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const golden = JSON.parse(fs.readFileSync(path.join(here, "fixtures", "golden.json"), "utf8"));

/** Mirrors the LCG used to capture the vectors. */
function seededRandom36(seed) {
  let state = seed >>> 0;
  return () => {
    state = (Math.imul(state, 1103515245) + 12345) >>> 0;
    return Math.floor(36 * (state / 2 ** 32));
  };
}

test("correlation ids match the legacy implementation", async () => {
  for (const vector of golden.correlation) {
    const correlation = await correlationIdFromKey(hexToBytes(vector.keyHex));
    assert.equal(correlation, vector.correlationId, `key ${vector.keyHex}`);
    assert.equal(correlation.length, 22);
  }
});

test("correlation ids are stable for the same key", async () => {
  const key = hexToBytes(golden.correlation[0].keyHex);
  assert.equal(await correlationIdFromKey(key), await correlationIdFromKey(key));
});

test("rolling base36 cipher matches the legacy implementation", () => {
  for (const vector of golden.encoder) {
    for (const item of vector.vectors) {
      assert.equal(
        encodeLabel(vector.keyCodes, item.plaintext),
        item.encoded,
        `plaintext=${JSON.stringify(item.plaintext)}`
      );
    }
  }
});

test("interaction labels match the legacy implementation", () => {
  for (const group of golden.labels) {
    const correlation = golden.correlation.find((c) => c.keyHex === group.keyHex).correlationId;
    const random36 = seededRandom36(group.seed);
    group.labels.forEach((expected, index) => {
      // Counts used when capturing the vectors.
      const counts = [0, 1, 2, 7, 15, 16, 255, 4096];
      assert.equal(
        interactionLabel(correlation, counts[index], { random36 }),
        expected,
        `count=${counts[index]} seed=${group.seed}`
      );
    });
  }
});

test("SessionGenerator output matches the legacy implementation", async () => {
  for (const vector of golden.sessionGen) {
    const generator = new SessionGenerator(hexToBytes(vector.keyHex));
    await generator.init();
    const random36 = seededRandom36(7);
    for (const expected of vector.urls) {
      const next = generator.next({ random36 });
      assert.equal(next.publicUrl, expected.publicUrl);
      assert.equal(next.privateUrl, expected.privateUrl);
    }
  }
});

test("private URL helper reproduces the legacy endpoint", () => {
  for (const vector of golden.correlation) {
    assert.equal(buildPrivateUrl(vector.keyB64), vector.privateUrl);
  }
});

test("byte/string helpers behave like the legacy versions", () => {
  const helpers = golden.helpers;
  const bytes = hexToBytes(helpers.keyHex);
  assert.equal(bytesToBigInt(bytes).toString(10), helpers.bigint);
  assert.equal(bytesToBase64(bytes), helpers.keyB64);
  assert.equal(utf8ToBase64("Привет, collaborate! 42"), helpers.utf8B64);
  assert.equal(base64ToUtf8(helpers.utf8B64), helpers.b64RoundTrip);
  assert.equal(keyToBase64(bytes), helpers.keyB64);
});

test("normalizeKeyB64 accepts valid keys and rejects wrong lengths", () => {
  assert.equal(normalizeKeyB64(golden.correlation[1].keyB64).length, 32);
  assert.throws(() => normalizeKeyB64(bytesToBase64(new Uint8Array(16))), /32 bytes/);
});

test("base36 encoder converts known values", () => {
  // The alphabet is letters-first ("abc…z012…9"), so digit 0 is "a", not "0".
  assert.equal(bigIntToBase36(0n), "");
  assert.equal(bigIntToBase36(36n), "ba");
  assert.equal(bigIntToBase36(1295n), "99");
  assert.equal(bigIntToBase36(7n, 4), "000h");

  for (const vector of golden.correlation) {
    const value = bytesToBigInt(hexToBytes(vector.keyHex));
    assert.equal(BigInt(`0x${vector.keyHex}`), value);
    assert.match(bigIntToBase36(value, 30), /^[a-z0-9]+$/);
  }
});
